const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, m => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[m]));
const norm = (v) => String(v ?? "").toLowerCase().replace(/ي/g, "ی").replace(/ك/g, "ک").replace(/\u200c/g, " ").replace(/\s+/g, " ").trim();
const val = (v, fallback = "—") => (v === null || v === undefined || String(v).trim() === "") ? fallback : String(v);
const intId = (id) => parseInt(String(id || "").replace(/\D/g, ""), 10) || 0;
const safeUrl = (url) => { try { const u = new URL(String(url)); return /^https?:$/.test(u.protocol) ? u.href : "#"; } catch (e) { return "#"; } };
const uniq = (arr) => [...new Set(arr.filter(v => v !== null && v !== undefined && String(v).trim() !== "").map(v => String(v).trim()))];

const state = {
  data: null, sources: [], filtered: [], page: 1, pageSize: 10, sort: "id-desc",
  tableSort: { sources: { key: "id", dir: "desc" }, legal: { key: "id", dir: "desc" }, research: { key: "date", dir: "desc" } },
  filters: { q: "", group: "", type: "", project: "", province: "", language: "", reliability: "", stance: "", organization: "", person: "", fullText: "", pdf: "", yearFrom: "", yearTo: "" },
  view: "overview"
};

const canonicalProjects = ["کوهرنگ ۱", "کوهرنگ ۲", "کوهرنگ ۳", "بهشت‌آباد", "گلاب", "چشمه‌لنگان", "خدنگستان", "خرسان ۳", "ماندگان", "گوکان", "پشندگان", "یلان", "بیده-ماربر", "بیده", "ماربر", "بن-بروجن", "انتقال کارون", "انتقال دز", "زاینده‌رود"];
function projectTags(s) {
  const raw = norm(s.Project);
  const tags = [];
  const aliases = [
    ["کوهرنگ ۱", ["کوهرنگ 1", "کوهرنگ اول", "کوهرنگ ۱"]],
    ["کوهرنگ ۲", ["کوهرنگ 2", "کوهرنگ دوم", "کوهرنگ ۲"]],
    ["کوهرنگ ۳", ["کوهرنگ 3", "کوهرنگ سوم", "کوهرنگ ۳"]],
    ["بهشت‌آباد", ["بهشت آباد", "بهشت‌آباد"]],
    ["گلاب", ["گلاب"]],
    ["چشمه‌لنگان", ["چشمه لنگان", "چشمه‌لنگان"]],
    ["خدنگستان", ["خدنگستان"]],
    ["خرسان ۳", ["خرسان 3", "خرسان ۳", "خرسان"]],
    ["ماندگان", ["ماندگان"]],
    ["گوکان", ["گوکان"]],
    ["پشندگان", ["پشندگان"]],
    ["یلان", ["یلان"]],
    ["بیده-ماربر", ["بیده-ماربر", "بیده ماربر"]],
    ["بیده", ["بیده"]],
    ["ماربر", ["ماربر"]],
    ["بن-بروجن", ["بن-بروجن", "بن بروجن"]],
    ["انتقال کارون", ["انتقال کارون", "کارون"]],
    ["انتقال دز", ["انتقال دز", "دز"]],
    ["زاینده‌رود", ["زاینده رود", "زاینده‌رود", "zayandeh"]]
  ];
  aliases.forEach(([name, aa]) => { if (aa.some(a => raw.includes(norm(a)))) tags.push(name); });
  return uniq(tags);
}
function provinceTags(s) {
  const raw = norm([s.Province, s.Location, s.Basin_Source, s.Basin_Destination].join(" "));
  const out = [];
  if (raw.includes("اصفهان")) out.push("اصفهان");
  if (raw.includes("چهارمحال")) out.push("چهارمحال‌وبختیاری");
  if (raw.includes("خوزستان")) out.push("خوزستان");
  if (raw.includes("ملی") || raw.includes("iran")) out.push("ملی");
  return uniq(out);
}
function sourceGroup(s, idSets) {
  const t = norm(s.Source_Type), id = s.Source_ID;
  if (idSets.legal.has(id) || /قانون|آیین|مصوب|تصویب|رأی|دادگاه|دیوان|حقوقی|سند رسمی|دستورالعمل|بخشنامه/.test(t)) return "حقوقی / رسمی";
  if (idSets.thesis.has(id) || /پایان|رساله|thesis|dissertation/.test(t)) return "پایان‌نامه / رساله";
  if (idSets.academic.has(id) || /مقاله|فصل کتاب|کنفرانس|علمی|journal|paper/.test(t)) return "علمی / دانشگاهی";
  if (idSets.parliament.has(id) || /مصاحبه|پارلمان|مجلس|اظهار|گفتگو|نطق|نامه/.test(t)) return "مصاحبه / موضع";
  if (idSets.social.has(id) || /شبکه اجتماعی|instagram|twitter|تلگرام/.test(t)) return "شبکه اجتماعی";
  if (idSets.news.has(id) || /خبر|گزارش|رسانه|روزنامه|آرشیو/.test(t)) return "خبر / رسانه";
  return "سایر";
}
function stanceGroup(s) {
  const x = norm(s.Position_Stance);
  if (/مخالف|انتقاد|critical|oppose|اعتراض/.test(x)) return x.includes("اعتراض") ? "اعتراضی" : "مخالف / انتقادی";
  if (/موافق|support|تأیید|حمایت/.test(x)) return "موافق / حمایتی";
  if (/قانون|حفاظت|حقوق/.test(x)) return "حقوقی / حفاظتی";
  if (/technical|فنی/.test(x)) return "فنی";
  if (/تحلیلی|خنثی|neutral|مناقشه/.test(x)) return "تحلیلی / خنثی";
  return val(s.Position_Stance);
}
function legalType(s) {
  const x = norm([s.Source_Type, s.Title, s.Topic, s.Organization, s.Publisher].join(" "));
  if (/دادگاه|دیوان|رأی|دادستان|قضایی|شعبه/.test(x)) return "آرای قضایی و دادگاه";
  if (/قانون|ماده [0-9۰-۹]+|مجلس شورای اسلامی/.test(x)) return "قانون";
  if (/آیین نامه|آیین‌نامه|تصویب نامه|تصویب‌نامه|مصوبه|شورای عالی آب|سیاست کلی|برنامه هفتم|برنامه ششم|برنامه چهارم/.test(x)) return "مصوبات و مقررات";
  if (/ارزیابی|محیط زیست|محیط‌زیست|eia|دستورالعمل|راهنما|تالاب/.test(x)) return "محیط‌زیست و ارزیابی";
  if (/وزارت نیرو|منابع آب|تخصیص|شرکت آب منطقه/.test(x)) return "وزارت نیرو و مدیریت منابع آب";
  return "سند و موضع رسمی";
}
function personName(s) { return val(s.Interviewee, val(s.Person, val(s.Author, ""))); }


function gregorianToJalali(gy, gm = 6, gd = 15) {
  const g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  let jy = (gy > 1600) ? 979 : 0;
  gy -= (gy > 1600) ? 1600 : 621;
  const gy2 = (gm > 2) ? gy : gy - 1;
  let days = 365 * gy + Math.floor((gy2 + 4) / 4) - Math.floor((gy2 + 100) / 100) + Math.floor((gy2 + 400) / 400) - 80 + gd + g_d_m[gm - 1];
  jy += 33 * Math.floor(days / 12053);
  days %= 12053;
  jy += 4 * Math.floor(days / 1461);
  days %= 1461;
  if (days > 365) {
    jy += Math.floor((days - 1) / 365);
  }
  return jy;
}

function parseShamsiYear(s) {
  const dpMatch = String(s.Date_Persian || "").match(/\b(1[234]\d{2})\b/);
  if (dpMatch) {
    const y = parseInt(dpMatch[1], 10);
    if (y <= 1406) return y;
  }
  const rawY = parseInt(String(s.Year || "").match(/\b\d{4}\b/)?.[0] || "", 10);
  if (rawY && rawY <= 1406) return rawY;

  const dg = String(s.Date_Gregorian || s.Year || "");
  const m = dg.match(/\b(\d{4})(?:-(\d{1,2}))?(?:-(\d{1,2}))?\b/);
  if (m) {
    const gy = parseInt(m[1], 10);
    if (gy <= 1406) return gy;
    const gm = m[2] ? parseInt(m[2], 10) : 6;
    const gd = m[3] ? parseInt(m[3], 10) : 15;
    return gregorianToJalali(gy, gm, gd);
  }

  if (rawY && rawY > 1406) return rawY - 621;
  return null;
}

function preprocess(data) {
  const c = data.collections || {};
  const idSets = { academic: new Set(c.academicIds || []), thesis: new Set(c.thesisIds || []), legal: new Set(c.legalIds || []), parliament: new Set(c.parliamentIds || []), news: new Set(c.newsIds || []), social: new Set(c.socialIds || []) };
  const sources = (data.sources || []).map(s => {
    const year = parseShamsiYear(s);
    const pTags = projectTags(s), prTags = provinceTags(s);
    const group = sourceGroup(s, idSets), stance = stanceGroup(s);
    const legal = idSets.legal.has(s.Source_ID);
    const blob = norm(Object.values(s).join(" "));
    return { ...s, _year: year, _projectTags: pTags, _provinceTags: prTags, _group: group, _stanceGroup: stance, _legal: legal, _legalType: legal ? legalType(s) : "", _person: personName(s), _blob: blob };
  });
  return { sources, idSets };
}
function countBy(items, fn) {
  const m = new Map(); items.forEach(x => { const k = fn(x); if (k && k !== "—") m.set(k, (m.get(k) || 0) + 1); });
  return [...m.entries()].sort((a, b) => b[1] - a[1]);
}
function fmt(n) { return new Intl.NumberFormat("fa-IR").format(Number(n) || 0) }
function showToast(msg) { const t = $("#toast"); t.textContent = msg; t.classList.add("show"); setTimeout(() => t.classList.remove("show"), 1800) }

async function boot() {
  let data = OFFLINE_FALLBACK;
  try {
    const r = await fetch("./data.json", { cache: "no-store" });
    if (r.ok) data = await r.json();
  } catch (e) { }
  state.data = data;
  const pre = preprocess(data);
  state.sources = pre.sources;
  state.filtered = [...state.sources];
  initTheme(); setupNavigation(); setupGlobalSearch(); setupQuickChips(); populateFilters(); renderAll(); bindActions(); setupSortableTables();
  $("#navSourcesCount").textContent = fmt(state.sources.length);
  $("#navLegalCount").textContent = fmt(state.sources.filter(s => s._legal).length);
  $("#sourceMeta").innerHTML = `${esc(data.meta.sourceFile)}<br>${fmt(state.sources.length)} منبع · ${esc(data.meta.lastSourceId || "")}`;
}

/* Theme Management */
function initTheme() {
  const saved = localStorage.getItem("theme") || "light";
  applyTheme(saved);
  const btn = $("#themeToggleBtn");
  if (btn) {
    btn.addEventListener("click", () => {
      const current = document.documentElement.getAttribute("data-theme") || "light";
      const next = current === "dark" ? "light" : "dark";
      applyTheme(next);
      // Re-render visual components if needed
      if (state.view === "overview") renderOverview();
      if (state.view === "research") renderResearch();
      if (state.view === "legal") renderLegal();
    });
  }
}

function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  localStorage.setItem("theme", theme);
  const btn = $("#themeToggleBtn");
  if (btn) {
    const isDark = theme === "dark";
    const icon = btn.querySelector(".theme-icon");
    const text = btn.querySelector(".theme-text");
    if (icon) icon.textContent = isDark ? "light_mode" : "dark_mode";
    if (text) text.textContent = isDark ? "حالت روز" : "حالت شب";
  }
}

/* Quick Filter Chips */
function setupQuickChips() {
  const chips = $$("#quickFilterChips .chip");
  if (!chips.length) return;
  chips.forEach(chip => {
    chip.addEventListener("click", () => {
      chips.forEach(c => c.classList.remove("active"));
      chip.classList.add("active");
      const target = chip.dataset.chip;
      handleQuickChip(target);
    });
  });
}

function handleQuickChip(target) {
  clearFilters();
  $$("#quickFilterChips .chip").forEach(c => c.classList.toggle("active", c.dataset.chip === target));

  if (target === "all") {
    // Already cleared
  } else if (target === "pdf") {
    state.filters.pdf = "Direct Link Available";
  } else if (target === "rel-a") {
    state.filters.reliability = "A";
  } else if (target === "legal") {
    state.filters.group = "اسناد رسمی و حقوقی";
  } else if (target === "academic") {
    state.filters.group = "علمی / دانشگاهی";
  } else if (target === "thesis") {
    state.filters.group = "پایان‌نامه / رساله";
  } else if (target === "koohrang3") {
    state.filters.project = "کوهرنگ ۳";
  } else if (target === "behesht") {
    state.filters.project = "بهشت‌آباد";
  } else if (target === "oppose") {
    state.filters.stance = "مخالف / انتقادی";
  }

  if ($("#filterGroup")) $("#filterGroup").value = state.filters.group;
  if ($("#filterReliability")) $("#filterReliability").value = state.filters.reliability;
  if ($("#filterPdf")) $("#filterPdf").value = state.filters.pdf;
  if ($("#filterProject")) $("#filterProject").value = state.filters.project;
  if ($("#filterStance")) $("#filterStance").value = state.filters.stance;

  state.page = 1;
  applyFilters();
}

function setupNavigation() {
  const closeSidebar = () => {
    $("#sidebar")?.classList.remove("open");
    $("#sidebarScrim")?.classList.remove("open");
    document.body.classList.remove("drawer-open");
  };
  const openSidebar = () => {
    $("#sidebar")?.classList.add("open");
    $("#sidebarScrim")?.classList.add("open");
    document.body.classList.add("drawer-open");
  };
  const toggleSidebar = () => {
    if ($("#sidebar")?.classList.contains("open")) {
      closeSidebar();
    } else {
      openSidebar();
    }
  };

  $$(".nav-item").forEach(btn => btn.addEventListener("click", () => {
    switchView(btn.dataset.view);
    closeSidebar();
  }));
  $$("[data-jump]").forEach(btn => btn.addEventListener("click", () => {
    switchView(btn.dataset.jump);
    closeSidebar();
  }));
  $("#menuBtn")?.addEventListener("click", toggleSidebar);
  $("#sidebarCloseBtn")?.addEventListener("click", closeSidebar);
  $("#sidebarScrim")?.addEventListener("click", closeSidebar);

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && $("#sidebar")?.classList.contains("open")) {
      closeSidebar();
    }
  });

  window.addEventListener("resize", () => {
    if (window.innerWidth > 768 && $("#sidebar")?.classList.contains("open")) {
      closeSidebar();
    }
  });
}

const titles = {
  overview: ["رصدخانه مطالعات و داده‌ها", "فراتحلیل و مرور ساختاریافته بانک شواهد و اسناد انتقال آب"],
  sources: ["بانک جامع شواهد و اسناد", "جستجو و فراتحلیل پیشرفته در پایگاه پژوهشی انتقال آب"],
  timeline: ["خط زمانی اسناد و تحولات", "ردیابی تاریخی رخدادها، مطالعات فنی و اسناد بالادستی"],
  legal: ["اسناد تقنینی، حقوقی و قضایی", "قوانین، مصوبات، آرای دیوان عدالت و گزارش‌های ارزیابی فنی"],
  projects: ["پروژه‌ها و طرح‌های انتقال", "پایش تطبیقی پوشش مطالعاتی و مواضع طرح‌های بین‌حوضه‌ای"],
  research: ["روش‌شناسی و لاگ کاوش", "مستندسازی فرآیند جستجو، پایگاه‌های استنادی و کلیدواژه‌ها"]
};

function switchView(view) {
  state.view = view;
  $$(".view").forEach(v => v.classList.toggle("active", v.id === `view-${view}`));
  $$(".nav-item").forEach(b => b.classList.toggle("active", b.dataset.view === view));
  const [t, st] = titles[view] || ["داشبورد", ""];
  $("#pageTitle").textContent = t;
  $("#pageSubtitle").textContent = st;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function setupGlobalSearch() {
  const gs = $("#globalSearch");
  if (!gs) return;
  gs.addEventListener("input", e => {
    const v = e.target.value.trim();
    if (!v) return;
    $("#sourceSearch").value = v;
    state.filters.q = v;
    state.page = 1;
    switchView("sources");
    applyFilters();
  });
  window.addEventListener("keydown", e => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
      e.preventDefault();
      gs.focus();
      gs.select();
    }
  });
}

function selectOptions(el, values, placeholder = "همه") {
  el.innerHTML = `<option value="">${esc(placeholder)}</option>` + values.map(v => `<option value="${esc(v)}">${esc(v)}</option>`).join("");
}

function populateFilters() {
  const s = state.sources;
  selectOptions($("#filterGroup"), uniq(s.map(x => x._group)), "همه گروه‌ها");
  selectOptions($("#filterType"), uniq(s.map(x => x.Source_Type)), "همه انواع");
  selectOptions($("#filterProject"), canonicalProjects, "همه پروژه‌ها");
  selectOptions($("#timelineProject"), canonicalProjects, "همه پروژه‌ها");
  selectOptions($("#legalProjectFilter"), canonicalProjects, "همه پروژه‌ها");
  selectOptions($("#filterProvince"), uniq(s.flatMap(x => x._provinceTags)), "همه استان‌ها");
  selectOptions($("#filterLanguage"), uniq(s.map(x => x.Language)), "همه زبان‌ها");
  selectOptions($("#filterStance"), uniq(s.map(x => x._stanceGroup)), "همه مواضع");
  selectOptions($("#filterOrganization"), uniq(s.map(x => x.Organization)), "همه نهادها");
  selectOptions($("#filterPerson"), uniq(s.map(x => x._person)), "همه اشخاص");
  selectOptions($("#legalTypeFilter"), uniq(s.filter(x => x._legal).map(x => x._legalType)), "همه انواع");
  const logs = state.data.searchLog || [];
  const dbKey = x => x["Database / Search Engine"] || x.Database || x["Database/Search Engine"] || "";
  selectOptions($("#researchDatabase"), uniq(logs.map(dbKey)), "همه پایگاه‌ها");
  selectOptions($("#researchLanguage"), uniq(logs.map(x => x.Language)), "همه زبان‌ها");
}

function renderAll() {
  renderOverview();
  renderSourceTable();
  renderTimeline();
  renderLegal();
  renderProjects();
  renderResearch();
}

function renderOverview() {
  const s = state.sources, legal = s.filter(x => x._legal).length;
  const pdf = s.filter(x => x.PDF_Status === "Direct Link Available").length;
  const academic = s.filter(x => x._group === "علمی / دانشگاهی").length;
  const theses = s.filter(x => x._group === "پایان‌نامه / رساله").length;
  const a = s.filter(x => x.Reliability === "A").length;
  const kpis = [
    ["کل منابع", s.length, "S001 تا " + (state.data.meta.lastSourceId || "—"), "database"],
    ["منابع علمی", academic, "مقاله، فصل کتاب و کنفرانس", "school"],
    ["پایان‌نامه و رساله", theses, "فارسی و انگلیسی", "menu_book"],
    ["حقوقی و رسمی", legal, "قانون، رأی، مصوبه و سند", "gavel"],
    ["کیفیت سطح A", a, `${Math.round(a / s.length * 100)}٪ از کل بانک`, "verified"],
    ["PDF مستقیم", pdf, "لینک مستقیم ثبت‌شده", "picture_as_pdf"]
  ];
  $("#kpiGrid").innerHTML = kpis.map(k => `<article class="kpi-card m3-card-elevated"><div class="kpi-icon-wrap"><span class="material-symbols-rounded kpi-icon">${k[3]}</span></div><div class="kpi-info"><div class="kpi-label">${esc(k[0])}</div><div class="kpi-value">${fmt(k[1])}</div><div class="kpi-note">${esc(k[2])}</div></div></article>`).join("");
  renderTrend($("#trendChart"), countBy(s.filter(x => x._year), x => x._year).sort((a, b) => a[0] - b[0]));
  renderDonut($("#reliabilityChart"), [["A", s.filter(x => x.Reliability === "A").length], ["B", s.filter(x => x.Reliability === "B").length], ["C", s.filter(x => x.Reliability === "C").length], ["D", s.filter(x => x.Reliability === "D").length]], "منبع");
  renderBars($("#sourceGroupChart"), countBy(s, x => x._group), 8);
  renderBars($("#projectChart"), countBy(s.flatMap(x => x._projectTags.map(t => ({ ...x, _tag: t }))), x => x._tag), 10, true, (name) => { state.filters.project = name; $("#filterProject").value = name; switchView("sources"); applyFilters() });
  renderBars($("#stanceChart"), countBy(s, x => x._stanceGroup), 7);
  const access = [["Full Text", s.filter(x => x.Full_Text === "Yes").length], ["PDF مستقیم", pdf], ["فقط Landing Page", s.filter(x => x.PDF_Status === "Landing Page Only").length], ["Full Text ناقص", s.filter(x => x.Full_Text === "Partial").length]];
  renderBars($("#accessChart"), access, 5);
  const recent = [...s].sort((a, b) => intId(b.Source_ID) - intId(a.Source_ID)).slice(0, 7);
  $("#recentSources").innerHTML = recent.map(x => `<div class="compact-source" data-source="${esc(x.Source_ID)}"><span class="source-id">${esc(x.Source_ID)}</span><span class="compact-title">${esc(x.Title)}</span><span class="compact-meta">${esc(x._group)}</span></div>`).join("");
  $$(".compact-source").forEach(r => r.addEventListener("click", () => openSource(r.dataset.source)));
}

function renderBars(el, entries, max = 8, clickable = false, onClick = null) {
  const arr = entries.slice(0, max), maxv = Math.max(...arr.map(x => x[1]), 1);
  el.innerHTML = `<div class="bar-list">${arr.map(([label, n]) => `<div class="bar-item ${clickable ? "clickable" : ""}" data-label="${esc(label)}"><div class="bar-label" title="${esc(label)}">${esc(label)}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2, n / maxv * 100)}%"></div></div><div class="bar-value">${fmt(n)}</div></div>`).join("")}</div>`;
  if (clickable && onClick) $$(".bar-item", el).forEach(r => r.addEventListener("click", () => onClick(r.dataset.label)));
}

function renderDonut(el, entries, centerLabel) {
  const total = entries.reduce((a, b) => a + b[1], 0) || 1;
  const isDark = document.documentElement.getAttribute("data-theme") === "dark";
  const colors = isDark
    ? ["#96ccff", "#53d7ee", "#b9c8da", "#fbc02d", "#ffb4ab", "#8cd890"]
    : ["#006399", "#006877", "#51606f", "#825500", "#ba1a1a", "#2e6b38"];
  let cursor = 0, stops = [];
  entries.forEach(([l, n], i) => { const p = n / total * 100; stops.push(`${colors[i % colors.length]} ${cursor}% ${cursor + p}%`); cursor += p });
  el.innerHTML = `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops.join(",")})"><div class="donut-center"><strong>${fmt(total)}</strong><span>${esc(centerLabel)}</span></div></div><div class="legend">${entries.map(([l, n], i) => `<div class="legend-item"><span class="legend-dot" style="background:${colors[i % colors.length]}"></span><span>${esc(l)}</span><span class="legend-value">${fmt(n)}</span></div>`).join("")}</div></div>`;
}

function renderTrend(el, entries) {
  if (!entries.length) { el.innerHTML = '<div class="empty-state">داده زمانی موجود نیست</div>'; return }
  const W = 760, H = 205, p = { l: 36, r: 16, t: 18, b: 32 }, max = Math.max(...entries.map(x => x[1]), 1);
  const total = entries.reduce((acc, x) => acc + x[1], 0);
  const minY = entries[0][0], maxY = entries.at(-1)[0], x = v => p.l + (v - minY) / (maxY - minY || 1) * (W - p.l - p.r), y = v => p.t + (1 - v / max) * (H - p.t - p.b);
  const pts = entries.map(([yr, n]) => [x(yr), y(n), yr, n]);
  const path = pts.map((q, i) => (i ? "L" : "M") + q[0].toFixed(1) + "," + q[1].toFixed(1)).join(" ");
  const area = `M${pts[0][0]},${H - p.b} ` + pts.map(q => `L${q[0]},${q[1]}`).join(" ") + ` L${pts.at(-1)[0]},${H - p.b} Z`;
  const ticks = [0, .25, .5, .75, 1].map(k => Math.round(max * k));
  const yearTicks = [...new Set([minY, Math.round(minY + (maxY - minY) * .25), Math.round(minY + (maxY - minY) * .5), Math.round(minY + (maxY - minY) * .75), maxY])];

  el.innerHTML = `<svg class="trend-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
    <defs>
      <linearGradient id="trendGradient" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="var(--chart-primary)" stop-opacity="0.35"/>
        <stop offset="65%" stop-color="var(--chart-primary)" stop-opacity="0.08"/>
        <stop offset="100%" stop-color="var(--chart-primary)" stop-opacity="0"/>
      </linearGradient>
    </defs>
    ${ticks.map(t => `<line class="grid-line" x1="${p.l}" x2="${W - p.r}" y1="${y(t)}" y2="${y(t)}"/><text class="axis-label" x="4" y="${y(t) + 4}">${fmt(t)}</text>`).join("")}
    <path class="trend-area" d="${area}"/>
    <path class="trend-line" d="${path}"/>
    ${pts.map(q => `<circle class="trend-point" data-year="${q[2]}" data-count="${q[3]}" cx="${q[0]}" cy="${q[1]}" r="3.5"><title>سال ${fmt(q[2])}: ${fmt(q[3])} منبع</title></circle>`).join("")}
    ${yearTicks.map(t => `<text class="axis-label" x="${x(t)}" y="${H - 8}" text-anchor="middle">${fmt(t)}</text>`).join("")}
  </svg>`;

  const tip = $("#chartTooltip");
  if (tip) {
    const circles = $$(".trend-point", el);
    circles.forEach(c => {
      c.addEventListener("mouseenter", () => {
        circles.forEach(item => item.classList.remove("active"));
        c.classList.add("active");
        const yr = c.dataset.year;
        const cnt = Number(c.dataset.count) || 0;
        const pct = total ? Math.round((cnt / total) * 100) : 0;
        tip.innerHTML = `<div class="tip-year">سال ${fmt(yr)}</div><div class="tip-count"><strong>${fmt(cnt)}</strong> منبع (${fmt(pct)}٪ از کل)</div>`;
        tip.style.display = "block";
        tip.style.opacity = "1";
        const rect = c.getBoundingClientRect();
        tip.style.left = `${rect.left + rect.width / 2}px`;
        tip.style.top = `${rect.top - 10}px`;
      });
      c.addEventListener("mouseleave", () => {
        c.classList.remove("active");
        tip.style.opacity = "0";
        setTimeout(() => { if (tip.style.opacity === "0") tip.style.display = "none"; }, 150);
      });
    });
  }
}

function bindActions() {
  const inputs = { sourceSearch: "q", filterGroup: "group", filterType: "type", filterProject: "project", filterProvince: "province", filterLanguage: "language", filterReliability: "reliability", filterStance: "stance", filterOrganization: "organization", filterPerson: "person", filterFullText: "fullText", filterPdf: "pdf", filterYearFrom: "yearFrom", filterYearTo: "yearTo" };
  Object.entries(inputs).forEach(([id, key]) => $("#" + id).addEventListener(id.includes("Search") || id.includes("Year") ? "input" : "change", e => { state.filters[key] = e.target.value; state.page = 1; applyFilters() }));
  $("#sortBy").addEventListener("change", e => { state.sort = e.target.value; const map = { "id-desc": ["id", "desc"], "id-asc": ["id", "asc"], "year-desc": ["year", "desc"], "year-asc": ["year", "asc"], rel: ["reliability", "asc"] }; const [key, dir] = map[state.sort]; state.tableSort.sources = { key, dir }; syncSortHeader("sources"); applyFilters() });
  $("#pageSize").addEventListener("change", e => { state.pageSize = +e.target.value; state.page = 1; renderSourceTable() });
  $("#clearFiltersBtn").addEventListener("click", clearFilters);
  $("#toggleFiltersBtn").addEventListener("click", () => $("#filterPanel").classList.toggle("collapsed"));
  $("#exportCsvBtn").addEventListener("click", () => exportSources(state.filtered, "water_sources_filtered.csv", "csv"));
  $("#quickExportBtn").addEventListener("click", () => exportSources(state.filtered.length ? state.filtered : state.sources, "water_sources.csv", "csv"));
  $("#exportExcelBtn").addEventListener("click", () => exportSources(state.filtered, "water_sources_filtered.xls", "xls"));
  $("#printBtn").addEventListener("click", () => window.print());
  $("#legalExportBtn").addEventListener("click", () => exportSources(getFilteredLegal(), "water_sources_legal.csv", "csv"));
  $("#projectSearch").addEventListener("input", renderProjects);
  ["timelineProject", "timelineFrom", "timelineTo", "timelineSearch"].forEach(id => $("#" + id).addEventListener(id === "timelineProject" ? "change" : "input", renderTimeline));
  ["legalSearch", "legalTypeFilter", "legalProjectFilter"].forEach(id => $("#" + id).addEventListener(id === "legalSearch" ? "input" : "change", renderLegalTable));
  ["researchSearch", "researchDatabase", "researchLanguage"].forEach(id => $("#" + id).addEventListener(id === "researchSearch" ? "input" : "change", renderResearchTable));
  $$("[data-close-modal]").forEach(x => x.addEventListener("click", closeModal));
}

function clearFilters() {
  Object.keys(state.filters).forEach(k => state.filters[k] = ""); state.page = 1;
  ["sourceSearch", "filterGroup", "filterType", "filterProject", "filterProvince", "filterLanguage", "filterReliability", "filterStance", "filterOrganization", "filterPerson", "filterFullText", "filterPdf", "filterYearFrom", "filterYearTo"].forEach(id => { if ($("#" + id)) $("#" + id).value = ""; });
  $$("#quickFilterChips .chip").forEach(c => c.classList.toggle("active", c.dataset.chip === "all"));
  applyFilters();
}

function applyFilters() {
  const f = state.filters;
  let arr = state.sources.filter(s => {
    if (f.q && !s._blob.includes(norm(f.q))) return false;
    if (f.group && s._group !== f.group) return false;
    if (f.type && val(s.Source_Type) !== f.type) return false;
    if (f.project && !s._projectTags.includes(f.project)) return false;
    if (f.province && !s._provinceTags.includes(f.province)) return false;
    if (f.language && val(s.Language) !== f.language) return false;
    if (f.reliability && s.Reliability !== f.reliability) return false;
    if (f.stance && s._stanceGroup !== f.stance) return false;
    if (f.organization && val(s.Organization) !== f.organization) return false;
    if (f.person && s._person !== f.person) return false;
    if (f.fullText && val(s.Full_Text) !== f.fullText) return false;
    if (f.pdf && val(s.PDF_Status) !== f.pdf) return false;
    if (f.yearFrom && (!s._year || s._year < +f.yearFrom)) return false;
    if (f.yearTo && (!s._year || s._year > +f.yearTo)) return false;
    return true;
  });
  const relRank = { A: 1, B: 2, C: 3, D: 4 };
  arr.sort((a, b) => {
    if (state.sort === "id-asc") return intId(a.Source_ID) - intId(b.Source_ID);
    if (state.sort === "year-desc") return (b._year || 0) - (a._year || 0) || intId(b.Source_ID) - intId(a.Source_ID);
    if (state.sort === "year-asc") return (a._year || 9999) - (b._year || 9999) || intId(a.Source_ID) - intId(b.Source_ID);
    if (state.sort === "rel") return (relRank[a.Reliability] || 9) - (relRank[b.Reliability] || 9) || intId(b.Source_ID) - intId(a.Source_ID);
    return intId(b.Source_ID) - intId(a.Source_ID);
  });
  state.filtered = arr; $("#filteredCount").textContent = fmt(arr.length); renderActiveFilters(); renderSourceTable();
}

function renderActiveFilters() {
  const f = state.filters;
  const labels = { q: "جستجو", group: "گروه", type: "نوع", project: "پروژه", province: "استان", language: "زبان", reliability: "کیفیت", stance: "موضع", organization: "نهاد", person: "شخص", fullText: "متن کامل", pdf: "PDF", yearFrom: "از سال", yearTo: "تا سال" };
  const active = Object.entries(f).filter(([k, v]) => Boolean(v));
  $("#activeFilters").innerHTML = active.map(([k, v]) => `<span class="active-filter-tag">${esc(labels[k] || k)}: <strong>${esc(v)}</strong><button data-clear-filter="${k}">×</button></span>`).join("");
  $$("[data-clear-filter]").forEach(b => b.addEventListener("click", () => {
    const k = b.dataset.clearFilter;
    state.filters[k] = "";
    const inputs = { q: "sourceSearch", group: "filterGroup", type: "filterType", project: "filterProject", province: "filterProvince", language: "filterLanguage", reliability: "filterReliability", stance: "filterStance", organization: "filterOrganization", person: "filterPerson", fullText: "filterFullText", pdf: "filterPdf", yearFrom: "filterYearFrom", yearTo: "filterYearTo" };
    if (inputs[k] && $("#" + inputs[k])) $("#" + inputs[k]).value = "";
    applyFilters();
  }));
}

function stanceClass(s) {
  if (s === "موافق / توجیه‌کننده") return "stance-pro";
  if (s === "مخالف / انتقادی") return "stance-oppose";
  return "stance-neutral";
}

const tableSortFields = {
  sources: ["id", "title", "group", "project", "year", "publisher", "reliability", "stance", null],
  legal: ["id", "title", "type", "project", "year", "organization", "reliability", null],
  research: ["query", "language", "database", "project", "type", "date", "results", null]
};

function latinDigits(str) {
  return String(str ?? "")
    .replace(/[۰-۹]/g, d => String.fromCharCode(d.charCodeAt(0) - 1728))
    .replace(/[٠-٩]/g, d => String.fromCharCode(d.charCodeAt(0) - 1584));
}

function sortValue(item, table, key) {
  if (!item || !key) return "";
  if (key === "id") return intId(item.Source_ID);
  if (key === "year") return item._year || 0;
  if (key === "reliability") {
    const relRank = { A: 1, B: 2, C: 3, D: 4 };
    return relRank[item.Reliability] || 9;
  }
  if (table === "sources") {
    if (key === "title") return item.Title || "";
    if (key === "group") return item._group || "";
    if (key === "project") return item._projectTags?.join("، ") || item.Project || "";
    if (key === "publisher") return item.Publisher || "";
    if (key === "stance") return item._stanceGroup || "";
  }
  if (table === "legal") {
    if (key === "title") return item.Title || "";
    if (key === "type") return item._legalType || item.Source_Type || "";
    if (key === "project") return item._projectTags?.join("، ") || item.Project || "";
    if (key === "organization") return item.Organization || item.Publisher || "";
  }
  if (table === "research") {
    if (key === "query") return item.Query || "";
    if (key === "language") return item.Language || "";
    if (key === "database") return item["Database / Search Engine"] || item.Database || item["Database/Search Engine"] || "";
    if (key === "project") return item.Project || "";
    if (key === "type") return item["Source Type"] || item.Source_Type || "";
    if (key === "date") {
      const d = latinDigits(item["Search Date"] || item.Search_Date || "").replace(/\D/g, "");
      return d ? parseInt(d.padEnd(8, "0").slice(0, 8), 10) : 0;
    }
    if (key === "results") {
      const n = parseInt(latinDigits(item["Number of useful results"] || item.Useful_Results || item["Useful Results"] || "").replace(/\D/g, ""), 10);
      return Number.isFinite(n) ? n : -1;
    }
  }
  return "";
}

function sortedTableRows(rows, table) {
  const cfg = state.tableSort[table];
  return [...rows].sort((a, b) => { const av = sortValue(a, table, cfg.key), bv = sortValue(b, table, cfg.key); if (av === bv) return 0; if (av === "" || av === "—") return 1; if (bv === "" || bv === "—") return -1; const c = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv), "fa", { numeric: true, sensitivity: "base" }); return cfg.dir === "asc" ? c : -c; });
}

function syncSortHeader(table) {
  const body = { sources: "#sourceTableBody", legal: "#legalTableBody", research: "#researchTableBody" }[table], tableEl = $(body)?.closest("table"), cfg = state.tableSort[table];
  tableEl?.querySelectorAll("thead th").forEach(h => h.setAttribute("aria-sort", h.dataset.sortKey === cfg.key ? (cfg.dir === "asc" ? "ascending" : "descending") : "none"));
}

function setupSortableTables() {
  const tables = { sources: "#sourceTableBody", legal: "#legalTableBody", research: "#researchTableBody" };
  Object.entries(tables).forEach(([table, bodySel]) => { const tableEl = $(bodySel)?.closest("table"); if (!tableEl) return; tableEl.querySelectorAll("thead th").forEach((th, i) => { const key = tableSortFields[table][i]; if (!key) return; th.dataset.sortKey = key; th.tabIndex = 0; th.setAttribute("role", "button"); const activate = () => { const cfg = state.tableSort[table]; cfg.dir = cfg.key === key && cfg.dir === "asc" ? "desc" : "asc"; cfg.key = key; syncSortHeader(table); if (table === "sources") renderSourceTable(); if (table === "legal") renderLegalTable(); if (table === "research") renderResearchTable(); }; th.addEventListener("click", activate); th.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); activate(); } }); }); syncSortHeader(table); });
}

function renderSourceTable() {
  const sorted = sortedTableRows(state.filtered, "sources"), start = (state.page - 1) * state.pageSize, page = sorted.slice(start, start + state.pageSize);
  $("#sourceTableBody").innerHTML = page.length ? page.map(s => `<tr data-source="${esc(s.Source_ID)}"><td class="source-id nowrap">${esc(s.Source_ID)}</td><td class="title-cell"><div class="title-main">${esc(s.Title)}</div><div class="title-sub"><span>${esc(val(s.Language))}</span>${s.DOI ? `<span>DOI</span>` : ""}</div></td><td>${esc(s._group)}<div class="title-sub">${esc(val(s.Source_Type))}</div></td><td>${esc(s._projectTags.join("، ") || val(s.Project))}</td><td class="nowrap">${esc(s._year || "—")}</td><td>${esc(val(s.Publisher))}</td><td><span class="badge rel-${esc(s.Reliability || "D")}">${esc(val(s.Reliability))}</span></td><td><span class="${stanceClass(s._stanceGroup)}">${esc(s._stanceGroup)}</span></td><td>${s.URL ? `<a class="m3-action-link" href="${safeUrl(s.URL)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"><span class="material-symbols-rounded">open_in_new</span><span>منبع</span></a>` : ""}${s.PDF_URL ? `<br><a class="m3-action-link pdf" href="${safeUrl(s.PDF_URL)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"><span class="material-symbols-rounded">picture_as_pdf</span><span>PDF</span></a>` : ""}</td></tr>`).join("") : '<tr><td colspan="9"><div class="empty-state">منبعی با این فیلترها پیدا نشد.</div></td></tr>';
  $$("tr[data-source]", $("#sourceTableBody")).forEach(r => r.addEventListener("click", () => openSource(r.dataset.source)));
  renderPagination();
}

function renderPagination() {
  const pages = Math.max(1, Math.ceil(state.filtered.length / state.pageSize)); if (state.page > pages) state.page = pages;
  const nums = []; for (let i = Math.max(1, state.page - 2); i <= Math.min(pages, state.page + 2); i++)nums.push(i);
  $("#pagination").innerHTML = `<button class="page-btn m3-page-btn" data-p="${state.page - 1}" ${state.page === 1 ? "disabled" : ""} aria-label="صفحه قبلی"><span class="material-symbols-rounded">chevron_right</span></button>${nums.map(i => `<button class="page-btn m3-page-btn ${i === state.page ? "active" : ""}" data-p="${i}">${fmt(i)}</button>`).join("")}<button class="page-btn m3-page-btn" data-p="${state.page + 1}" ${state.page === pages ? "disabled" : ""} aria-label="صفحه بعدی"><span class="material-symbols-rounded">chevron_left</span></button><span class="m3-pagination-info" style="color:var(--md-sys-color-on-surface-variant);font-size:0.8rem;margin-right:12px">از ${fmt(pages)} صفحه</span>`;
  $$(".page-btn[data-p]", $("#pagination")).forEach(b => b.addEventListener("click", () => { const p = +b.dataset.p; if (p >= 1 && p <= pages) { state.page = p; renderSourceTable(); window.scrollTo({ top: 260, behavior: "smooth" }) } }));
}

function filteredTimeline() {
  const p = $("#timelineProject").value, q = norm($("#timelineSearch").value), f = +$("#timelineFrom").value || 0, t = +$("#timelineTo").value || 9999;
  return state.sources.filter(s => s._year && s._year >= f && s._year <= t && (!p || s._projectTags.includes(p)) && (!q || s._blob.includes(q))).sort((a, b) => a._year - b._year || intId(a.Source_ID) - intId(b.Source_ID));
}

function renderTimeline() {
  const arr = filteredTimeline(); $("#timelineCountBadge").textContent = `${fmt(arr.length)} منبع`;
  renderTrend($("#timelineHistogram"), countBy(arr, x => x._year).sort((a, b) => a[0] - b[0]));
  $("#timelineList").innerHTML = arr.length ? arr.map(s => `<div class="timeline-event"><div class="timeline-year">${esc(s._year)}</div><div class="timeline-dot"></div><article class="panel timeline-card m3-card" data-source="${esc(s.Source_ID)}"><h4>${esc(s.Title)}</h4><p>${esc(val(s.Summary, ""))}</p><div class="timeline-tags"><span class="tag">${esc(s.Source_ID)}</span><span class="tag">${esc(s._group)}</span>${s._projectTags.slice(0, 2).map(x => `<span class="tag">${esc(x)}</span>`).join("")}<span class="badge rel-${esc(s.Reliability || "D")}">${esc(val(s.Reliability))}</span></div></article></div>`).join("") : '<div class="empty-state">رخدادی در این بازه پیدا نشد.</div>';
  $$(".timeline-card").forEach(r => r.addEventListener("click", () => openSource(r.dataset.source)));
}

function getFilteredLegal() {
  const q = norm($("#legalSearch")?.value), type = $("#legalTypeFilter")?.value, proj = $("#legalProjectFilter")?.value;
  return state.sources.filter(s => s._legal).filter(s => {
    if (q && !s._blob.includes(q)) return false;
    if (type && s._legalType !== type) return false;
    if (proj && !s._projectTags.includes(proj)) return false;
    return true;
  });
}

function renderLegal() {
  const all = state.sources.filter(s => s._legal);
  const types = countBy(all, x => x._legalType);
  const judicial = all.filter(x => x._legalType === "آرای قضایی و دادگاه").length, laws = all.filter(x => x._legalType === "قانون").length, env = all.filter(x => x._legalType === "محیط‌زیست و ارزیابی").length, a = all.filter(x => x.Reliability === "A").length;
  const k = [
    ["کل اسناد حقوقی", all.length, "ثبت‌شده در اسناد رسمی", "policy"],
    ["قوانین و مواد", laws, "قوانین و مصوبات", "gavel"],
    ["احکام قضایی", judicial, "دیوان عدالت و دادگاه", "balance"],
    ["محیط‌زیست / EIA", env, "ارزیابی و الزامات", "eco"],
    ["کیفیت سطح A", a, "منابع اولیه و معتبر", "verified"]
  ];
  $("#legalKpis").innerHTML = k.map(x => `<article class="kpi-card m3-card-elevated"><div class="kpi-icon-wrap"><span class="material-symbols-rounded kpi-icon">${x[3]}</span></div><div class="kpi-info"><div class="kpi-label">${esc(x[0])}</div><div class="kpi-value">${fmt(x[1])}</div><div class="kpi-note">${esc(x[2])}</div></div></article>`).join("");
  renderBars($("#legalTypeChart"), types, 8);
  renderBars($("#legalOrgChart"), countBy(all, x => val(x.Organization, val(x.Publisher))).slice(0, 10), 10);
  renderLegalTable();
}

function renderLegalTable() {
  const arr = sortedTableRows(getFilteredLegal(), "legal");
  $("#legalTableBody").innerHTML = arr.length ? arr.map(s => `<tr data-source="${esc(s.Source_ID)}"><td class="source-id">${esc(s.Source_ID)}</td><td class="title-cell"><div class="title-main">${esc(s.Title)}</div><div class="title-sub">${esc(val(s.Source_Type))}</div></td><td>${esc(s._legalType)}</td><td>${esc(s._projectTags.join("، ") || val(s.Project))}</td><td>${esc(s._year || "—")}</td><td>${esc(val(s.Organization, val(s.Publisher)))}</td><td><span class="badge rel-${esc(s.Reliability || "D")}">${esc(val(s.Reliability))}</span></td><td>${s.URL ? `<a class="m3-action-link" href="${safeUrl(s.URL)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"><span class="material-symbols-rounded">open_in_new</span><span>اصل سند</span></a>` : "—"}</td></tr>`).join("") : '<tr><td colspan="8"><div class="empty-state">سندی پیدا نشد.</div></td></tr>';
  $$("tr[data-source]", $("#legalTableBody")).forEach(r => r.addEventListener("click", () => openSource(r.dataset.source)));
}

function renderProjects() {
  const q = norm($("#projectSearch")?.value);
  const canonical = (state.data.projects || []).map(x => x.Project).filter(Boolean);
  const names = uniq([...canonical, ...state.sources.flatMap(s => s._projectTags)]).filter(n => !q || norm(n).includes(q));
  const cards = names.map(name => {
    const arr = state.sources.filter(s => s._projectTags.includes(name) || norm(s.Project) === norm(name)), count = arr.length, a = arr.filter(x => x.Reliability === "A").length, pdf = arr.filter(x => x.PDF_URL).length, years = arr.map(x => x._year).filter(Boolean);
    return { name, count, a, pdf, min: years.length ? Math.min(...years) : null, max: years.length ? Math.max(...years) : null };
  }).filter(x => x.count).sort((a, b) => b.count - a.count);
  const max = Math.max(...cards.map(x => x.count), 1);
  $("#projectCards").innerHTML = cards.map(x => `<article class="panel project-card m3-card" data-project="${esc(x.name)}"><h3>${esc(x.name)}</h3><div class="project-count">${fmt(x.count)}</div><div class="project-meta">${fmt(x.a)} منبع A · ${fmt(x.pdf)} PDF مستقیم ${x.min ? `· ${x.min}–${x.max}` : ""}</div><div class="project-meter"><span style="width:${x.count / max * 100}%"></span></div></article>`).join("");
  $$(".project-card").forEach(c => c.addEventListener("click", () => { state.filters.project = c.dataset.project; $("#filterProject").value = state.filters.project; switchView("sources"); applyFilters() }));
}

function renderResearch() {
  const logs = state.data.searchLog || [];
  const dbKey = x => x["Database / Search Engine"] || x.Database || x["Database/Search Engine"] || "نامشخص";
  renderBars($("#databaseChart"), countBy(logs, dbKey), 12);
  renderDonut($("#searchLanguageChart"), countBy(logs, x => val(x.Language)), "Query");
  renderResearchTable();
}

function renderResearchTable() {
  const q = norm($("#researchSearch")?.value), db = $("#researchDatabase")?.value || "", lang = $("#researchLanguage")?.value || "";
  const arr = sortedTableRows((state.data.searchLog || []).filter(x => {
    const database = x["Database / Search Engine"] || x.Database || x["Database/Search Engine"] || "";
    return (!q || norm(Object.values(x).join(" ")).includes(q)) && (!db || database === db) && (!lang || val(x.Language) === lang);
  }), "research");
  $("#researchTableBody").innerHTML = arr.length ? arr.map(x => `<tr><td class="title-cell"><div class="title-main">${esc(x.Query || "—")}</div></td><td>${esc(val(x.Language))}</td><td>${esc(val(x["Database / Search Engine"] || x.Database || x["Database/Search Engine"]))}</td><td>${esc(val(x.Project))}</td><td>${esc(val(x["Source Type"] || x.Source_Type))}</td><td>${esc(val(x["Search Date"] || x.Search_Date))}</td><td>${esc(val(x["Number of useful results"] || x.Useful_Results || x["Useful Results"]))}</td><td>${esc(val(x.Notes))}</td></tr>`).join("") : '<tr><td colspan="8"><div class="empty-state">رکوردی پیدا نشد.</div></td></tr>';
}

const COLUMN_NAMES_FA = {
  Source_ID: "شناسه منبع (Source ID)",
  Document_ID: "شناسه سند (Document ID)",
  Title: "عنوان منبع",
  Title_EN: "عنوان انگلیسی",
  Date_Gregorian: "تاریخ میلادی",
  Date_Persian: "تاریخ شمسی",
  Year: "سال انتشار",
  Language: "زبان منبع",
  Source_Type: "نوع دقیق منبع",
  Publisher: "ناشر / منبع انتشار",
  Author: "نویسنده / پدیدآور",
  Interviewee: "مصاحبه‌شونده",
  Person: "شخص / چهره مرتبط",
  Position: "سمت / جایگاه حقوقی",
  Organization: "سازمان / نهاد مسئول",
  Province: "استان",
  Location: "موقعیت جغرافیایی / شهر",
  Project: "پروژه انتقال آب",
  Basin_Source: "حوضه آبریز مبدأ",
  Basin_Destination: "حوضه آبریز مقصد",
  Topic: "موضوع محتوایی",
  Position_Stance: "موضع‌گیری (موافق/مخالف)",
  Primary_or_Secondary: "مرتبه منبع (دست اول / ثانویه)",
  Reliability: "درجه اعتبار (Reliability)",
  Full_Text: "دسترسی به متن کامل",
  PDF_Status: "وضعیت فایل PDF",
  PDF_URL: "پیوند مستقیم فایل PDF",
  Local_PDF: "نام فایل در آرشیو محلی",
  SHA256: "هش اصالت فایل (SHA-256)",
  URL: "پیوند وبگاه اصلی",
  Canonical_URL: "پیوند استاندارد (Canonical)",
  Archive_URL: "پیوند آرشیو پایدار",
  DOI: "شناسه دیجیتال (DOI)",
  Summary: "خلاصه منبع",
  Key_Claim: "ادعای اصلی / یافته کلیدی",
  Quote: "نقل‌قول مستقیم ثبت‌شده",
  Notes: "یادداشت‌ها و توضیحات"
};

function colFa(key) {
  return COLUMN_NAMES_FA[key] || String(key).replace(/_/g, " ");
}

function openSource(id){
  const s=state.sources.find(x=>x.Source_ID===id);if(!s)return;
  const links=[
    s.URL?`<a class="btn btn-primary m3-btn m3-btn-filled" href="${safeUrl(s.URL)}" target="_blank" rel="noopener"><span class="material-symbols-rounded">open_in_new</span><span>منبع اصلی ↗</span></a>`:"",
    s.PDF_URL?`<a class="btn btn-secondary m3-btn m3-btn-tonal" href="${safeUrl(s.PDF_URL)}" target="_blank" rel="noopener"><span class="material-symbols-rounded">download</span><span>PDF مستقیم ↓</span></a>`:"",
    s.DOI?`<a class="btn btn-secondary m3-btn m3-btn-outlined" href="${safeUrl("https://doi.org/"+String(s.DOI).replace(/^https?:\/\/(dx\.)?doi\.org\//i,""))}" target="_blank" rel="noopener"><span class="material-symbols-rounded">link</span><span>DOI ↗</span></a>`:"",
    `<button class="btn btn-ghost m3-btn m3-btn-text" id="copyCitationBtn"><span class="material-symbols-rounded">content_copy</span><span>کپی ارجاع</span></button>`
  ].join("");
  const facts=[
    ["نوع منبع", s.Source_Type],
    ["گروه منبع", s._group],
    ["تاریخ انتشار", s.Date_Gregorian || s.Date_Persian || s.Year],
    ["زبان", s.Language],
    ["ناشر / منبع", s.Publisher],
    ["نویسنده", s.Author],
    ["شخص / مصاحبه‌شونده", s.Interviewee || s.Person],
    ["سمت", s.Position],
    ["سازمان / نهاد", s.Organization],
    ["استان", s.Province],
    ["پروژه انتقال آب", s.Project],
    ["درجه اعتبار (Reliability)", s.Reliability],
    ["موضع‌گیری", s.Position_Stance],
    ["دسترسی به متن کامل", s.Full_Text],
    ["وضعیت فایل PDF", s.PDF_Status],
    ["شناسه سند", s.Document_ID]
  ].filter(x => x[1]);

  const mainKeys=new Set(["Title","Title_EN","Summary","Key_Claim","Quote","Notes","URL","PDF_URL","DOI","Canonical_URL"]);
  const raw=Object.entries(s).filter(([k,v])=>!k.startsWith("_")&&!mainKeys.has(k)&&v!==null&&v!==undefined&&String(v).trim()!=="");

  $("#modalContent").innerHTML=`
    <div class="modal-id">${esc(s.Source_ID)}</div>
    <h2 id="modalTitle">${esc(s.Title)}</h2>
    ${s.Title_EN?`<p class="modal-title-en">${esc(s.Title_EN)}</p>`:""}
    <div class="modal-actions">${links}</div>
    <div class="modal-grid">
      ${facts.map(([k,v])=>`<div class="modal-fact"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join("")}
    </div>
    ${s.Summary?`<div class="content-block"><h4>خلاصه سند</h4><p>${esc(s.Summary)}</p></div>`:""}
    ${s.Key_Claim?`<div class="content-block"><h4>ادعای اصلی / یافته کلیدی</h4><p>${esc(s.Key_Claim)}</p></div>`:""}
    ${s.Quote?`<div class="content-block"><h4>نقل‌قول مستقیم ثبت‌شده</h4><p>${esc(s.Quote)}</p></div>`:""}
    ${s.Notes?`<div class="content-block"><h4>یادداشت‌ها</h4><p>${esc(s.Notes)}</p></div>`:""}
    <div class="content-block">
      <h4>اطلاعات کامل رکورد</h4>
      <div class="raw-details">
        ${raw.map(([k,v])=>`
          <div class="raw-row">
            <span class="raw-key" title="${esc(k)}">${esc(colFa(k))}</span>
            <strong class="raw-val">${esc(v)}</strong>
          </div>
        `).join("")}
      </div>
    </div>
  `;

  $("#sourceModal").classList.add("open");
  $("#sourceModal").setAttribute("aria-hidden","false");
  document.body.style.overflow="hidden";
  $("#copyCitationBtn")?.addEventListener("click",()=>copyCitation(s));
}

function closeModal() { $("#sourceModal").classList.remove("open"); $("#sourceModal").setAttribute("aria-hidden", "true"); document.body.style.overflow = "" }

function copyCitation(s) {
  const text = [s.Author || s.Interviewee || s.Person, s.Year, `«${s.Title}»`, s.Publisher, s.DOI ? `DOI: ${s.DOI}` : "", s.URL || ""].filter(Boolean).join("، ");
  navigator.clipboard?.writeText(text).then(() => showToast("ارجاع منبع در کلیپ‌بورد کپی شد")).catch(() => showToast("امکان کپی خودکار وجود ندارد"));
}

function exportSources(arr, filename, type) {
  const cols = [["Source_ID", "Source ID"], ["Title", "عنوان"], ["Date_Gregorian", "تاریخ میلادی"], ["Date_Persian", "تاریخ شمسی"], ["Year", "سال"], ["Language", "زبان"], ["Source_Type", "نوع منبع"], ["Publisher", "ناشر"], ["Author", "نویسنده"], ["Interviewee", "مصاحبه‌شونده"], ["Person", "شخص"], ["Position", "سمت"], ["Organization", "نهاد"], ["Province", "استان"], ["Project", "پروژه"], ["Topic", "موضوع"], ["Position_Stance", "موضع"], ["Summary", "خلاصه"], ["Key_Claim", "ادعای اصلی"], ["URL", "URL"], ["DOI", "DOI"], ["PDF_URL", "PDF"], ["Full_Text", "Full Text"], ["Reliability", "Reliability"], ["Notes", "یادداشت"]];
  if (type === "xls") {
    const html = `<html><head><meta charset="utf-8"></head><body><table border="1"><tr>${cols.map(x => `<th>${esc(x[1])}</th>`).join("")}</tr>${arr.map(s => `<tr>${cols.map(x => `<td>${esc(val(s[x[0]], ""))}</td>`).join("")}</tr>`).join("")}</table></body></html>`;
    downloadBlob(new Blob(["\ufeff", html], { type: "application/vnd.ms-excel;charset=utf-8" }), filename); showToast("فایل Excel سازگار ایجاد شد"); return;
  }
  const q = v => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const csv = [cols.map(x => q(x[1])).join(","), ...arr.map(s => cols.map(x => q(s[x[0]])).join(","))].join("\r\n");
  downloadBlob(new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" }), filename); showToast(`${fmt(arr.length)} رکورد خروجی گرفته شد`);
}

function downloadBlob(blob, filename) { const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = filename; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove() }, 100) }

boot();
